<?php
namespace app\service;
class SecretStore{private static function keyPath():string{return (string)(getenv('LUMEN_SETTINGS_KEY_FILE')?:'/www/server/lumenapi/settings.key');}private static function key():string{$raw=trim((string)@file_get_contents(self::keyPath()));$k=hex2bin($raw);if($k===false||strlen($k)!==32)throw new \RuntimeException('secret_key_invalid');return$k;}public static function encrypt(string $plain):string{if($plain==='')return'';$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($plain,'aes-256-gcm',self::key(),OPENSSL_RAW_DATA,$iv,$tag);if($cipher===false)throw new \RuntimeException('secret_encrypt_failed');return'enc:v1:'.base64_encode($iv.$tag.$cipher);}public static function decrypt(string $value):string{if(!str_starts_with($value,'enc:v1:'))return$value;$raw=base64_decode(substr($value,7),true);if($raw===false||strlen($raw)<29)throw new \RuntimeException('secret_cipher_invalid');$iv=substr($raw,0,12);$tag=substr($raw,12,16);$plain=openssl_decrypt(substr($raw,28),'aes-256-gcm',self::key(),OPENSSL_RAW_DATA,$iv,$tag);if($plain===false)throw new \RuntimeException('secret_decrypt_failed');return$plain;}}
